return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Hungarian','last-translator' => 'Diego Versiani','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','po-revision-date' => '2025-05-22 13:20+0000','language' => 'hu_HU','x-generator' => 'Loco https://localise.biz/','x-loco-version' => '2.7.2; wp-6.8.1','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Menjen a Plugin kereséshez','Activate %s' => 'Aktiválja %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => 'A <strong>%1$s</strong> telepítéséhez és aktiválásához <strong>%2$s</strong> telepítése és aktiválása szükséges. <a href="%4$s">%3$s</a>','Enter your code here' => 'Adja meg a kódot itt','Add %s' => '%s hozzáadása','Remove' => 'Távolítsa el a','Order number and receipt will be sent to this email address.' => 'A rendelés számát és a nyugtát erre az e-mail címre küldjük.','Apartment, unit, building, floor, etc.' => 'Lakás, egység, épület, emelet stb.','Shipping phone' => 'Szállítótelefon','Only used for shipping-related questions.' => 'Csak szállítással kapcsolatos kérdések esetén használható.','Single step' => 'Egyetlen lépés','Click to go to the order summary' => 'Kattintson ide a rendelés összefoglalójához','Cart total:' => 'Kosár összesen:','Proceed to %s' => 'Folytassa %s','Proceed to contact' => 'Lépjen kapcsolatba a kapcsolattartóval','Proceed to shipping' => 'Tovább a szállításhoz','Proceed to billing' => 'Tovább a számlázáshoz','Proceed to payment' => 'Folytassa a fizetést','Shipping method' => 'Szállítási mód','Additional notes' => 'További megjegyzések','Payment method' => 'Fizetési mód','Step %1$s of %2$s' => '%1$s. lépés a %2$s-ből.','Change: %s' => 'Változás: %s','Not selected yet.' => 'Még nincs kiválasztva.','Same as shipping address' => 'Ugyanaz, mint a szállítási cím','Same as billing address' => 'Ugyanaz, mint a számlázási cím','Order summary' => 'Összefoglaló a rendelésről','Edit cart' => 'Kosár szerkesztése','Did you mean %s?' => 'Úgy értetted %s?','Change email address to: {suggestion-value}' => 'Módosítsa az e-mail címét: {suggestion-value}','This is a required field.' => 'Ez egy kötelező mező.','This is not a valid email address.' => 'Ez nem érvényes e-mail cím.','This field does not match the related field value.' => 'Ez a mező nem felel meg a kapcsolódó mező értékének.','The CPF number "{cpf_number}" is invalid.' => 'A "{cpf_number}" CPF-szám érvénytelen.','The CNPJ number "{cnpj_number}" is invalid.' => 'A "{cnpj_number}" CNPJ szám érvénytelen.','(Required)' => '(Kötelező)','Checkout Header - Desktop' => 'Pénztár fejléc - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Widgetek megjelenítése a pénztár fejlécén a nagy képernyőkön. Csak akkor jelenik meg, ha a plugin pénztárgép fejlécét használja.','Checkout Header - Mobile' => 'Pénztár fejléc - Mobil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'A pénztár fejléc alatti widgetek megjelenítése mobileszközökön. Csak akkor jelenik meg, ha a plugin pénztárgép fejlécét használja.','Checkout Sidebar' => 'Pénztár oldalsáv','Display widgets on the checkout sidebar after the order summary.' => 'Widgetek megjelenítése a pénztár oldalsávján a rendelés összefoglalója után.','Checkout Order Summary' => 'Pénztári rendelés összesítése','Display widgets inside the order summary at the checkout page.' => 'Widgetek megjelenítése a rendelés összegzésében a pénztár oldalra.','Checkout Below Place Order' => 'Pénztár alul Rendelés leadása','Display widgets below the place order button at the checkout page.' => 'Widgetek megjelenítése a rendelés leadása gomb alatt a pénztár oldalon.','Checkout Footer' => 'Pénztár lábléc','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Widgetek megjelenítése a pénztár láblécében. Csak akkor jelenik meg, ha a plugin pénztárgép láblécét használja.','Classic' => 'Klasszikus','Boxed' => 'Dobozos','Split' => 'Split','Minimalist' => 'Minimalista','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Folyékony pénztár és szállítási dátum pluginok a CodeRockz által','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Észrevettük, hogy a CodeRockz által készített Delivery & Pickup Date Time for WooCommerce (ingyenes és PRO) plugint használja. Az integráció ezekkel a pluginekkel átkerült a Fluid Checkout PRO-hoz.</p>','Upgrade to PRO' => 'Frissítés PRO-ra','Fluid Checkout database updated successfully' => 'Fluid Checkout adatbázis sikeresen frissült','The database changes where applied successfully.' => 'Az adatbázis módosításait sikeresen alkalmazták.','Dismiss' => 'Elutasíthatod','Fluid Checkout database update' => 'Fluid Checkout adatbázis frissítés','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Néhány változtatásra van szükség az adatbázisban. Mint minden frissítés esetén, javasoljuk, hogy <strong>készítsen teljes biztonsági mentést a weboldaláról, mielőtt folytatja</strong>.','Update database' => 'Adatbázis frissítése','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'A Fluid Checkout nem kompatibilis a Divi Builder pénztár elrendezéssel','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>A Fluid Checkout-nak szüksége van a klasszikus WooCommerce rövidkód alapú pénztár űrlapra, hogy működjön. Ha a Divi Buildert használja a pénztár oldal megjelenésének testreszabásához, a klasszikus rövidkódokat a Divi Builder egyéni widgetjei helyettesítik a pénztár oldal minden egyes részéhez. Ezek az egyéni widgetek nem kompatibilisek a Fluid Checkout funkcióval.</p><p>Kérlek, szerkeszd meg a pénztár oldaladat, és cseréld le a Divi Builder widgeteket egy szöveges widgetre, amely a rövidkódot <code>[woocommerce_checkout]</code> tartalmazza.</p>Az egyéni widgetek nem kompatibilisek a Fluid Checkout funkcióval.','Edit the checkout page' => 'A pénztár oldal szerkesztése','Read the documentation.' => 'Olvassa el a dokumentációt.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'A német nyelvű PRO többlépcsős pénztár funkciót ki kell kapcsolni a Fluid Checkout használatakor','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'A Fluid Checkout használata esetén a Germanized PRO plugin többlépcsős funkciója szükségtelenné válik, és <strong>kritikus hibákat okozhat az új megrendelések feldolgozása során</strong>. Kérjük, tiltsa le a Germanized PRO többlépcsős pénztár funkciót a plugin beállításaiban.','Go to Germanized settings' => 'Menjen a németesített beállításokhoz','Thanks for choosing Fluid Checkout!' => 'Köszönjük, hogy a Fluid Checkoutot választotta!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Ön már egy ideje használja a plugint. Hogy tetszik eddig? <br>Kérlek, adj egy gyors értékelést, minden visszajelzést értékelünk, és ez arra ösztönöz minket, hogy folyamatosan fejlesszük a plugint :)','Rate the plugin' => 'Értékelje a plugint','I need help!' => 'Segítségre van szükségem!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'A Quadlayers által készített WooCommerce Checkout Manager egyes funkciói nem feltétlenül működnek a várt módon, ha a Fluid Checkout-tal együtt használja. További információkért és alternatív megoldásokért olvassa el <a href="%s">dokumentációnkat</a>.','Read documentation' => 'Dokumentáció olvasása','Don\'t show this again' => 'Ne mutasd meg ezt még egyszer!','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'További tervezési sablonok','Optimized cart page' => 'Optimalizált kosár oldal','Optimized order received / thank you page' => 'Optimalizált megrendelés érkezett / köszönöm oldal','Edit cart contents at checkout page' => 'Kosár tartalmának szerkesztése a pénztár oldalon','Account matching / user matching' => 'Számlaillesztés / felhasználóillesztés','Trust symbols on the cart and thank you pages' => 'Bizalom szimbólumok a kosár és a köszönöm oldalakon','More positions for the coupon code on the checkout page' => 'További pozíciók a kuponkód a pénztár oldalon','International phone numbers' => 'Nemzetközi telefonszámok','Gift messages and packing slips' => 'Ajándéküzenetek és csomagolólapok','Local pickup and in-store collection' => 'Helyi átvétel és bolti átvétel','EU-VAT Assistant' => 'EU-VAT asszisztens','I already have it – Hide this offer' => 'Már megvan - Rejtsd el ezt az ajánlatot','Activated' => 'Aktivált','Address book' => 'Címjegyzék','Select an image' => 'Kép kiválasztása','Cart layout' => 'Kosár elrendezése','Cart optimizations' => 'Kosár optimalizálás','Enable cart page optimizations' => 'Engedélyezze a kosároldal optimalizálását','Header and footer template' => 'Fejléc és lábléc sablon','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Azt szabályozza, hogy a zavaró tényezők nélküli oldal fejlécét és láblécét használja-e, vagy megtartja az aktuálisan aktív téma fejlécét és láblécét.','Distraction free header and footer' => 'Zavartalan fejléc és lábléc','Theme\'s header and footer' => 'Téma fejléc és lábléc','Cart elements' => 'Kosár elemek','Make the order summary stay visible on the cart page while scrolling' => 'Legyen látható a rendelés összefoglalója a kosár oldalon görgetés közben is','Coupon codes' => 'Kupon kódok','Hidden' => 'Rejtett','Before the cart items section' => 'A kosár elemek szakasza előtt','Inside the cart items section' => 'A kosár elemek részlegén belül','After the cart items section' => 'A kosár elemek szakasza után','Before the shipping section' => 'A szállítási szakasz előtt','After the shipping section' => 'A szállítási szakasz után','Before the order summary' => 'A rendelési összefoglaló előtt','Inside the order summary' => 'A megrendelés összefoglalójában','Before the order totals' => 'A rendelési összegek előtt','After the order totals' => 'Miután a rendelési összegek','After the order summary' => 'A rendelés összefoglalója után','Shipping' => 'Szállítás','Select position where to display the shipping costs and calculator on the cart page.' => 'Válassza ki azt a pozíciót, ahol a szállítási költséget és a kalkulátort a kosár oldalán megjeleníti.','Display as a cart section' => 'Kosár részként való megjelenítés','Cross-sells' => 'Keresztértékesítések','Select position where to display the cross-sells section on the cart page.' => 'Válassza ki, hogy hol jelenjen meg a keresztértékesítések szakasza a kosároldalon.','Before the cart actions' => 'A kosár akciók előtt','After the cart actions' => 'A kosár akciók után','Layout of cross-sell items on the cart page.' => 'A kereszteladásos tételek elrendezése a kosároldalon.','Optimized horizontal cross-sells layout' => 'Optimalizált vízszintes keresztértékesítések elrendezése','Theme\'s cross-sells layout' => 'A téma keresztértékesítések elrendezése','Number of cross-sell items to display on the cart page' => 'A kosároldalon megjelenítendő keresztértékesítési tételek száma','Add widget areas to the cart page' => 'Widget területek hozzáadása a kosár oldalhoz','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ezeket a widget területeket arra használják, hogy bizalmi szimbólumokat és bizalmi jelvényeket adjanak hozzá a kosároldalon.','Checkout' => 'Pénztár','Checkout layout' => 'Pénztár elrendezése','Design template' => 'Tervezési sablon','Dark mode' => 'Sötét üzemmód','Enable dark mode' => 'Sötét üzemmód engedélyezése','Logo image' => 'Logó kép','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Válassza ki a pénztár oldal fejlécében megjelenítendő képet. Csak akkor érvényes, ha a figyelemelterelésmentes fejlécet és láblécet használja.','Header background color' => 'Fejléc háttérszín','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Válasszon háttérszínt a pénztár oldal fejlécéhez. Csak akkor érvényes, ha a figyelemelterelésmentes fejlécet és láblécet használja.','HTML color value. ie: #f3f3f3' => 'HTML színérték. pl: #f3f3f3','Page background color' => 'Oldal háttérszín','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Válasszon háttérszínt a pénztár oldalhoz. A szín a <em>body</em> elemre kerül alkalmazásra.','Footer background color' => 'Lábléc háttérszín','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Válasszon háttérszínt a pénztár oldal láblécéhez. Csak akkor érvényes, ha a figyelemelterelésmentes fejlécet és láblécet használja.','Progress bar' => 'Haladás sáv','Display the checkout progress bar when using multi-step checkout layout' => 'A pénztár előrehaladási sávjának megjelenítése többlépcsős pénztár elrendezés használata esetén','Make the checkout progress bar stay visible while scrolling' => 'A pénztár előrehaladási sávjának görgetés közben is láthatóvá tétele','Express checkout' => 'Expressz pénztár','Enable the express checkout section' => 'Az expressz pénztár rész engedélyezése','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Megjeleníti az expressz pénztár részleget a pénztárnál, ha a támogatott fizetési átjárók engedélyezik ezt a funkciót.','Display express checkout buttons in one line for larger screens' => 'Expressz pénztár gombok egy sorban történő megjelenítése nagyobb képernyőkön','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'További kötelező mezők figyelmen kívül hagyása, ha kompatibilis expressz pénztár fizetési átjáróval fizetsz','Make the order summary stay visible while scrolling' => 'Görgetés közben is látható maradjon a rendelés összefoglalója','Choose a background color for the order summary section.' => 'Válasszon háttérszínt a megrendelés összefoglaló részéhez.','Highlight the order totals row in the order summary table' => 'Jelölje ki a rendelés összesítő táblázatban a rendelésösszegek sorát.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Leginkább akkor hasznos, ha a megrendelés összefoglaló szakasza nem rendelkezik kiemelt háttérszínnel. A Fluid Checkout PRO használata esetén a Kosár, a Megrendelés beérkezett és a Megrendelés megtekintése oldalakra is alkalmazható.','Action link on the order summary at checkout.' => 'Akció link a rendelés összesítésénél a pénztárnál.','Edit cart link' => 'Kosár link szerkesztése','Cart items count' => 'Kosár elemek száma','Link to shop page' => 'Link a bolt oldalához','Cart items' => 'Kosár elemek','Hide cart items errors at the checkout page' => 'A kosár tételek hibáinak elrejtése a pénztár oldalon','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Ne jelenítse meg a kosár tételek hibája üzenetet a pénztár oldal tetején. A vásárlás befejezéséhez a pénztár űrlap elküldésekor ezek a hibaüzenetek mindig megjelennek.','Place order' => 'Rendelés leadása','Define the position to display "Place order" and terms checkbox section.' => 'Határozza meg a "Megrendelés leadása" és a feltételek jelölőnégyzet szakaszának megjelenítési pozícióját.','Some options might not be compatible with some plugins and themes.' => 'Egyes opciók nem feltétlenül kompatibilisek egyes bővítményekkel és témákkal.','Below the payment section' => 'A fizetési szakasz alatt','Below the order summary' => 'A rendelés összefoglalója alatt','Both below the payment section and the order summary' => 'Mind a fizetési rész, mind a megrendelés összefoglalója alatt','Add widget areas to the checkout page' => 'Widget területek hozzáadása a pénztár oldalhoz','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ezeket a widget területeket arra használják, hogy bizalmi szimbólumokat és bizalmi jelvényeket adjanak hozzá a pénztároldalon.','Display the coupon codes section title' => 'A kupon kódok szakasz címének megjelenítése','Select position where to display the coupon codes section on the checkout page.' => 'Válassza ki, hogy hol jelenjen meg a kuponkódok szakasza a pénztár oldalon.','Before the checkout steps' => 'A pénztári lépések előtt','As a substep before payment methods' => 'A fizetési módok előtti allépésként','As a substep after payment methods' => 'A fizetési módok utáni allépésként','Default button style' => 'Alapértelmezett gomb stílusa','"Add" link button' => '"Hozzáadás" link gomb','Checkout fields' => 'Pénztár mezők','Optional fields' => 'Választható mezők','Hide optional fields behind a link button' => 'Opcionális mezők elrejtése egy link gomb mögött','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'A nyitott beviteli mezők számának csökkentése érdekében ajánlott ezt az opciót bejelölve tartani, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">olvassa el a kutatást</a>.','Do not hide "Address line 2" fields behind a link button' => 'Ne rejtse el a "Címsor 2" mezőt egy link gomb mögé.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Csak akkor ajánlott, ha a legtöbb ügyfélnek valóban szüksége van a "Címsor 2" mezőre, vagy ha a helyes szállítási cím megadása döntő fontosságú (pl. élelmiszerek és más romlandó termékek szállítása esetén).','Billing address' => 'Számlázási cím','Select position where to display the billing address section on the checkout page.' => 'Válassza ki, hogy hol jelenjen meg a számlázási cím rész a pénztár oldalra.','As a step before shipping' => 'A szállítás előtti lépésként','As a sub-step before the shipping address section' => 'A szállítási cím szakasz előtti allépésként','As a sub-step after the shipping address section' => 'A szállítási cím szakasz utáni allépésként','As a step after shipping' => 'A szállítás utáni lépésként','As a sub-step before the payment section' => 'A fizetési szakasz előtti allépésként','Force billing and shipping addresses to the same (single section)' => 'Kényszerítse a számlázási és szállítási címeket ugyanarra a címre (egyetlen szekció)','Checkbox for "Same as shipping/billing address" checked by default' => 'A "Ugyanaz, mint a szállítási/számlázási cím" jelölőnégyzet alapértelmezés szerint be van jelölve.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'A "Ugyanaz, mint a szállítási cím" jelölőnégyzet alapértelmezés szerint be lesz jelölve, amikor a szállítási cím szakasz jelenik meg először. <br>A "Ugyanaz, mint a számlázási cím" jelölőnégyzet alapértelmezés szerint akkor kezd el jelölődni, amikor a számlázási cím szakasz jelenik meg először. <br> Javasoljuk, hogy hagyja bejelölve ezt az opciót, mivel így jelentősen csökkentheti a nyitott beviteli mezők számát a pénztárnál, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">olvassa el a kutatást</a>.','Highlight the billing address section in the checkout form' => 'Jelölje ki a számlázási cím részt a pénztár űrlapon.','Shipping address' => 'Szállítási cím','Highlight the shipping address section in the checkout form' => 'Jelölje ki a szállítási cím részt a pénztár űrlapon.','Shipping methods' => 'Szállítási módok','Choose in which position to display the shipping methods section.' => 'Válassza ki, hogy melyik pozícióban jelenjen meg a szállítási módok szakasz.','Before shipping address' => 'Szállítási cím előtt','After shipping address' => 'Szállítási cím után','Local pickup' => 'Helyi átvétel','Removes shipping address section when a local pickup shipping method is selected.' => 'Eltávolítja a szállítási cím részt, ha helyi átvételi szállítási módot választ.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'A szállítási címet a helyi átvételi pont helyével helyettesíti, ha helyi átvételi szállítási módot választ.','Choose which address to save as the shipping address for local pickup orders.' => 'Válassza ki, hogy melyik címet mentse el szállítási címként a helyi átvételi rendelésekhez.','Save the selected pickup location' => 'A kiválasztott átvételi hely mentése','Save same as the billing address' => 'A számlázási címmel megegyező mentés','Do not save any shipping address' => 'Ne mentse el a szállítási címet','Company name field for shipping address' => 'Cégnév mező a szállítási címhez','Change visibility for the company name field for the shipping address section on the checkout form.' => 'A cégnév mező láthatóságának módosítása a szállítási cím szakaszban a pénztár űrlapon.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ha a mező "opcionális", ami az alapértelmezett láthatósági állapot, akkor a rendszer nem alkalmazza a változtatásokat, hogy a többi bővítmény alkalmazhassa a szükséges változtatásokat.','Hidden (remove field)' => 'Rejtett (mező eltávolítása)','Optional' => 'Opcionális','Required' => 'Kötelező','Add shipping phone field to the checkout form.' => 'Szállítási telefon mező hozzáadása a pénztár űrlaphoz.','Choose in which step to display the shipping phone field.' => 'Válassza ki, hogy melyik lépésben jelenjen meg a szállítási telefon mező.','Contact step' => 'Kapcsolat lépés','Billing phone' => 'Számlázási telefon','Add billing phone field to the checkout form.' => 'Számlázási telefon mező hozzáadása a pénztár űrlaphoz.','Choose in which step to display the billing phone field.' => 'Válassza ki, hogy melyik lépésben jelenjen meg a számlázási telefon mező.','Show country code beside the flag' => 'Országkód megjelenítése a zászló mellett','Show an example of a valid phone number inside phone fields' => 'Példa az érvényes telefonszámra a telefonmezőkben','Do not change placeholders' => 'Ne változtassa meg a helyőrzőket','Show if not defined' => 'Megjelenítés, ha nincs definiálva','Always show' => 'Mindig mutasd meg','Order notes' => 'Megrendelési jegyzetek','Define the visibility of the additional order notes field.' => 'A további rendelési megjegyzések mező láthatóságának meghatározása.','Gift options' => 'Ajándékozási lehetőségek','Allow customers to add a gift message and other gift related options to the order.' => 'Lehetővé teszi az ügyfelek számára, hogy ajándéküzenetet és egyéb ajándékkal kapcsolatos opciókat adjanak a megrendeléshez.','Display the gift message as part of the order details table instead of a separate section' => 'Az ajándék üzenet megjelenítése a megrendelés részleteit tartalmazó táblázat részeként, nem pedig külön részként.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ez az opció a megrendelés visszaigazoló oldalát (köszönöm oldal) és a megrendelés adatait érinti a számlaoldalakon, az e-mailekben és a csomagolólapokon.','Account matching' => 'Számlaegyeztetés','Enable the account matching feature' => 'A számlaillesztési funkció engedélyezése','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'A vendég vásárló megrendeléseinek összekapcsolása a meglévő fiókjával, ha már létezik egy fiók a vásárló elérhetőségi adataival.','Display message when an account exists with the email address provided' => 'Üzenet megjelenítése, ha a megadott e-mail címmel létezik fiók','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'A fiók létrehozásának mezőit egy értesítéssel és a bejelentkezés lehetőségével helyettesíti. Bizonyos körülmények között ajánlott lehet ezt a lehetőséget kikapcsolva hagyni az ügyfelek adatainak védelme érdekében.','Dashboard' => 'Műszerfal','Integrations' => 'Integrációk','License keys' => 'Licenckulcsok','Visit our website for more information about our plugins and add-ons.' => 'Látogasson el weboldalunkra, ahol bővítményeinkről és kiegészítőinkről további információkat talál.','Order pay page' => 'Megrendelés fizetős oldal','Order pay' => 'Fizetés megrendelése','Enable order pay page optimizations' => 'Engedélyezze a fizetős oldal optimalizálását','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Megváltoztatja a megrendelés kifizetése oldal elrendezését a meglévő megrendelések esetében, amelyek az ügyféltől való fizetésre várnak.','Add widget areas to the order pay page' => 'Widget területek hozzáadása a megrendelés fizetési oldalhoz','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Ezek a widget területek a bizalmi szimbólumok és bizalmi jelvények hozzáadására szolgálnak a megrendelés fizetési oldalán.','Thank you page & order details layout' => 'Köszönöm oldal & rendelés részleteinek elrendezése','Order details optimizations' => 'Rendelési részletek optimalizálása','Enable thank you page and order details optimizations' => 'Engedélyezze a köszönöm oldal és a rendelés részleteinek optimalizálását','Changes the layout of order details on the thank you page and account pages.' => 'Megváltoztatja a megrendelés adatainak elrendezését a köszönöm oldalon és a számlaoldalakon.','Enable order details customizations on email notifications' => 'A rendelési részletek testreszabásának engedélyezése az e-mail értesítéseken','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Új szakaszok megjelenítése és a szakaszok sorrendjének módosítása az e-mail értesítésekben. Az e-mail értesítésekben a rendelés részleteinek stílusa változatlan marad.','Thank you page' => 'Köszönöm oldal','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Ezek a beállítások a köszönöm oldalra, más néven a megrendelés beérkezése vagy a megrendelés visszaigazolása oldalra hatnak.','Order details layout' => 'A megrendelés részleteinek elrendezése','Display the order details with wide layout on the thank you page' => 'A megrendelés részleteinek megjelenítése széles elrendezésben a köszönöm oldalon','Add widget areas to the thank you page' => 'Widget területek hozzáadása a köszönöm oldalhoz','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ezeket a widget területeket arra használják, hogy bizalmi szimbólumokat és bizalmi jelvényeket adjanak hozzá a köszönőoldalon.','Order actions' => 'Megrendelési műveletek','Choose in which position to display the order actions.' => 'Válassza ki, hogy melyik pozícióban jelenjenek meg a rendelési műveletek.','Inside the order overview' => 'A rendelés áttekintése','After the order overview' => 'A rendelés áttekintése után','After order sections' => 'A rendelési szakaszok után','Order status' => 'Megrendelés státusza','Display the order status progress bar' => 'A rendelés állapotának előrehaladási sávjának megjelenítése','Choose in which position to display the section.' => 'Válassza ki, hogy melyik pozícióban jelenjen meg a szakasz.','After the order overview and payment instructions' => 'A megrendelés áttekintése és a fizetési utasítások után','Before the order items section' => 'A rendelési tételek szakasz előtt','Inside the order items section' => 'A rendelési tételek szakaszon belül','After the order items section' => 'A rendelési tételek szakasz után','On the sidebar' => 'Az oldalsávon','Order downloads' => 'Letöltések megrendelése','Gift message' => 'Ajándék üzenet','Tools' => 'Eszközök','Troubleshooting' => 'Hibaelhárítás','Debug options' => 'Hibakeresési lehetőségek','Debug mode' => 'Hibakeresési mód','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'A hibakeresési mód használata befolyásolja a webhely teljesítményét. Csak hibaelhárításkor használja ezt az opciót.','Load unminified assets' => 'Minimalizálatlan eszközök betöltése','Enhanced select fields' => 'Továbbfejlesztett mezők kiválasztása','Fix automatic zoom-in on form fields' => 'Az űrlapmezők automatikus nagyításának javítása','Set <code>font-size</code> inside form fields to 16px' => '<code>font-size</code> beállítása az űrlapmezőkben 16px-re','Fluid Checkout' => 'Folyadék ellenőrzése','Settings' => 'Beállítások','Support' => 'Támogatás','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Újítson PRO-ra</a> a további lehetőségek felszabadításához.','(PRO)' => '(PRO)','(experimental)' => '(kísérleti)','Please verify your phone number.' => 'Kérjük, ellenőrizze telefonszámát.','The Bluehost Plugin' => 'A Bluehost plugin','Custom fields' => 'Egyéni mezők','Enable custom shipping email field' => 'Egyéni szállítási e-mail mező engedélyezése','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Ha engedélyezve van, a Bluehost plugin szállítási e-mail mezője hozzáadódik a pénztár űrlaphoz.','Captcha Pro by BestWebSoft' => 'Captcha Pro by BestWebSoft','Captcha position' => 'Captcha pozíció','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Határozza meg a captcha szakasz megjelenítésének pozícióját. A kiválasztott captcha típusától függően előfordulhat, hogy egyes pozíciók nem működnek.','Selecting a pickup point is required before proceeding.' => 'A folytatás előtt ki kell választani egy átvételi pontot.','Pickup point' => 'Átvételi pont','Pickup point not selected yet.' => 'A felvételi pont még nincs kiválasztva.','Pickup point:' => 'Felszállási pont:','Mailchimp for WooCommerce' => 'Mailchimp a WooCommerce számára','Subscribe checkbox' => 'Feliratkozás jelölőnégyzet','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Felülírja a feliratkozás jelölőnégyzet pozícióját a pénztár oldalon, és mindig a kapcsolat lépésnél jelenítse meg azt.','Before Shipping Address' => 'Szállítási cím előtt','(originally "%s")' => '(eredetileg "%s")','After Shipping Address' => 'Szállítási cím után','Selecting a collection point is required when shipping with FermoPoint.' => 'A FermoPointtal történő szállítás esetén szükséges a gyűjtőhely kiválasztása.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ha be van jelölve, a felhasználóknak küldött e-mailben elgépelésről tájékoztat. (Ez a funkció ki van kapcsolva, mert a Fluid Checkout kínálja a funkciót. Az opció módosítása nem lép hatályba)','Enable Mail Check: (disabled feature)' => 'Mail-ellenőrzés engedélyezése: (letiltott funkció)','Carrier:' => 'Hordozó:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'Feliratkozás checkbox pozíció','Move the sign up checkbox to the contact step' => 'A feliratkozás jelölőnégyzetének áthelyezése a kapcsolat lépésbe','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Ha engedélyezve van, a jelölőnégyzet a Sendinblue plugin beállításaiban meghatározott megjelenítési helytől függetlenül a kapcsolati lépcsőre kerül.','Theme Betheme' => 'Téma Betheme','Checkout progress' => 'Pénztár előrehaladása','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'A Betheme pénztári lépések szakaszának kimenete a pénztár, a kosár és a megrendelés beérkezése oldalakon.','Theme Fennik' => 'Téma Fennik','Breadcrumbs' => 'Morzsa','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'A Fennik téma kimenete a kenyérmorzsák szakasza a Fluid Checkout fejléc és lábléc használata esetén.','Theme Go' => 'Téma Go','My account layout' => 'A fiókom elrendezése','Enable wide layout on "My account" page.' => 'Széles elrendezés engedélyezése a "Fiókom" oldalon.','Theme Impreza' => 'Téma Impreza','Header' => 'Fejléc','Spacing for site header at the checkout page (in pixels)' => 'A webhely fejlécének távolsága a pénztár oldalnál (pixelben)','Only applicable when using the Impreza theme header at the checkout page.' => 'Csak akkor alkalmazható, ha az Impreza téma fejlécét használja a pénztár oldalon.','Theme Kapee' => 'Téma Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'A Kapee téma pénztári lépések szakaszának kimenete a pénztár, a kosár és a megrendelés beérkezése oldalakon.','Theme Porto' => 'Téma Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'A Porto téma pénztári lépések szakaszának kimenete a pénztár, a kosár és a megrendelés beérkezése oldalakon.','Theme Pressmart' => 'Téma Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'A Pressmart téma pénztári lépések szakaszának kiadása a pénztár, a kosár és a megrendelés beérkezése oldalakon.','Theme The Gem' => 'Téma A drágakő','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'A The Gem téma pénztári lépések szakaszának kimenete a Fluid Checkout fejléc és lábléc használata esetén.','Theme Woodmart' => 'Téma Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'A Woodmart téma pénztári lépések szakaszának kimenete a Fluid Checkout fejléc és lábléc használata esetén.','Checkout options' => 'Pénztári opciók','Disable the theme checkout options' => 'A téma pénztári beállításainak kikapcsolása','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'A téma által hozzáadott termékkép, mennyiség mező, eltávolítás gomb és a termékoldalra mutató link alapértelmezés szerint ki vannak kapcsolva.','Theme Atomion' => 'Téma Atomion','Order progress' => 'Megrendelés előrehaladása','Display order progress from the theme' => 'Megrendelés előrehaladásának megjelenítése a témában','Display the form field labels visible on the page' => 'Az űrlapmezők címkéinek megjelenítése az oldalon látható módon','It is recommended to keep this option enabled for a better user experience.' => 'A jobb felhasználói élmény érdekében ajánlott engedélyezve hagyni ezt az opciót.','Theme ZK Nito' => 'Téma ZK Nito','Add extra fields to the checkout form' => 'Extra mezők hozzáadása a pénztár űrlaphoz','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Hozzáad egy extra szállítási e-mail és szállítási telefon mezőt a szállítási cím részhez.','Go to the home page' => 'Menjen a főoldalra','Skip to content' => 'Ugrás a tartalomra','Create an account' => 'Fiók létrehozása','Log in to your account' => 'Jelentkezzen be fiókjába','Already have an account?' => 'Már van fiókja?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Bejelentkezett %1$s néven. <a href="%2$s">Kijelentkezés</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Az Ön megrendelésének teljes összege %s. Nincs szükség további fizetésre.','Close and continue with checkout' => 'Bezárás és folytatás a pénztárral','Continue' => 'Folytatás','Parcel terminal' => 'Csomagterminál','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ezt a widgetet a Fluid Checkout váltotta fel. </p><p>A Fluid Checkout használata esetén a pénztár oldalnak az eredeti WooCommerce rövidkódot <code>[woocommerce_checkout]</code> kell használnia, hogy megfelelően működjön.</p><p>Bővebb információért látogasson el a Fluid Checkout dokumentációba.</p>A Fluid Checkout dokumentációba.</p>','Theme The7' => 'Téma The7','Additional header sections' => 'További fejléc szakaszok','Output additional header sections if enabled in the theme settings.' => 'További fejlécrészek kiadása, ha a téma beállításaiban engedélyezve van.','More information' => 'További információ','Pick a Locker' => 'Válassz egy szekrényt','Page template' => 'Oldal sablon','Use `Order confirmation` page template for block-based themes' => 'A "Megrendelés megerősítése" oldal sablon használata blokk alapú témákhoz','Only applies when using a block-based theme.' => 'Csak akkor érvényes, ha blokkalapú témát használ.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe átjáró','Payment form' => 'Fizetési űrlap','Apply styles to the Stripe payment form fields' => 'Stílusok alkalmazása a Stripe fizetési űrlap mezőire','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Ha engedélyezve van, a Fluid Checkout a pluginnal való kompatibilitásra optimalizált stílusokat alkalmazza. Ezt érdemes letiltani, ha egyéni stílusokat használ a Stripe fizetési űrlap mezőihez.','Theme Nyture' => 'Téma Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'A pénztárlépések szakaszának kimenete a Nyture témából a Fluid Checkout használatakor.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Lehetővé teszi a vásárlók számára, hogy olyan megrendelésekre fizessenek, amelyeket vagy az áruház adminisztrátora hozott létre kézzel, vagy nem fejezte be a pénztár során.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'A Quadlayers által készített WooCommerce Checkout Manager plugin nem kompatibilis a Fluid Checkouttal','Company name field for billing address' => 'Cégnév mező a számlázási címhez','Change visibility for the company name field for the billing address section on the checkout form.' => 'A cégnév mező láthatóságának módosítása a számlázási cím szakaszban a pénztár űrlapon.','Theme Bookshelf' => 'Téma könyvespolc','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'A Bookshelf téma pénztárlépések szakaszának kimenete a Fluid Checkout használatakor.','Account password' => 'Fiók jelszó','An account will be created with the information provided at checkout when completing the order.' => 'A fiókot a pénztárnál megadott adatokkal hozzuk létre a megrendelés befejezésekor.','Choose the style of the progress bar.' => 'Válassza ki az előrehaladási sáv stílusát.','Bars' => 'Bárok','Theme Ireca' => 'Téma Ireca','WooCommerce page layout' => 'WooCommerce oldal elrendezése','Force wide layout on WooCommerce pages' => 'Széles elrendezés kikényszerítése a WooCommerce oldalakon','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Ez biztosítja, hogy a tartalmi rész ne legyen túl szűk a WooCommerce oldalakon, beleértve a pénztár, a kosár, a kapott megrendelés, a megrendelés kifizetése és a fiók oldalakat.','WooCommerce Smart Coupons' => 'WooCommerce intelligens kuponok','Position on checkout page' => 'Pozíció a pénztár oldalra','Choose where to display the available coupons section on the checkout page.' => 'Válassza ki, hogy hol jelenjen meg az elérhető kuponok rész a pénztár oldalain.','Before the progress bar' => 'Az előrehaladási sáv előtt','After the progress bar' => 'Az előrehaladási sáv után','Before coupon codes section' => 'Mielőtt kupon kódok szakasz','Format phone numbers according to the rules for each country.' => 'Formázza a telefonszámokat az egyes országok szabályainak megfelelően.','Use precise phone number validation' => 'Használjon pontos telefonszám-érvényesítést','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ez egy kísérleti funkció, és előfordulhat, hogy nem minden beállításban működik a várt módon. Óvatosan használja.','Phone number validation types used when precise validation is enabled.' => 'A telefonszám érvényesítésének típusai, ha a pontos érvényesítés engedélyezve van.','Mobile' => 'Mobil','Fixed line' => 'Vezetékes vonal','Toll free' => 'Díjmentes','Or' => 'Vagy','Contact' => 'Kapcsolat','Multi step' => 'Több lépés','2 columns' => '2 oszlop','1 column' => '1 oszlop','Before checkout steps' => 'A pénztár előtti lépések','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Az <em>"1 oszlop"</em> pénztár elrendezés használata esetén ez a beállítás mindig <em>"A pénztár lépései előtt"</em>-ra van állítva, és az asztali nézetre is vonatkozik.','Position for the extra order summary section on mobile.' => 'Az extra rendelési összefoglaló rész mobilon történő elhelyezése.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'A <em>"A webhely fejlécén"</em> csak akkor érvényes, ha a figyelemelterelés nélküli fejlécet használja.','On the site header (requires distraction-free header)' => 'Az oldal fejlécén (figyelemelterelés-mentes fejlécet igényel)','Initial state for the expansible order summary section on mobile.' => 'A bővíthető rendelési összefoglaló rész kezdeti állapota mobilon.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'A szabályozási követelmények miatt a következő országok esetében javasoljuk, hogy a <em>bővített</em> értéket állítsa be: <strong>Németország</strong>, <strong>Ausztria</strong>, <strong>Svájc</strong>, <strong>Hollandia</strong>, <strong>Lengyelország</strong>, <strong>Belgium</strong> és <strong>Franciaország</strong>.','Collapsed' => 'Összeomlott','Expanded' => 'Kibővített','Do not show' => 'Ne mutassa','yes' => 'igen','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'A szállítási telefonszám mező „kötelező” mezőként jelenhet meg, ha a számlázási cím szakasz a szállítási cím szakasz után jelenik meg, és a számlázási telefonszám mező „kötelező” beállítású. Erre azért van szükség, hogy a szállítási cím átmásolható legyen a számlázási címbe, ha az adott opció be van jelölve; ellenkező esetben előfordulhat, hogy az ügyfél nem tudja kitölteni a fizetési űrlapot.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'A számlázási telefonszám mező „kötelező” mezőként jelenhet meg, ha a számlázási cím szakasz a szállítási cím szakasz előtt jelenik meg, és a szállítási telefonszám mező „kötelező” beállítású. Erre azért van szükség, hogy a szállítási cím átmásolható legyen a számlázási címbe, ha az adott opció be van jelölve; ellenkező esetben előfordulhat, hogy az ügyfél nem tudja kitölteni a fizetési űrlapot.','Settings profiles' => 'Beállítási profilok','Settings profile' => 'Beállítási profil','You do not have permission to perform this action.' => 'Nincs jogosultsága erre a műveletre.','You do not have permission to activate plugins.' => 'Nincs jogosultsága a bővítmények aktiválására.','Missing plugin.' => 'Hiányzó bővítmény.','Plugin activated.' => 'A bővítmény aktiválva.','The following changes will be applied:' => 'A következő módosítások kerülnek végrehajtásra:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'A Fluid Checkout 5.0 verziótól kezdve a beállítások mentése más módon történik. A korábbi beállítások továbbra is az adatbázisban maradnak, hogy szükség esetén vissza lehessen állni a korábbi verziókra.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Az üzleted már körülbelül 2 hete az új beállításokkal működik, így lehetőséged volt megtisztítani az adatbázisban tárolt régi beállításokat. Kérjük, vedd figyelembe, hogy a tisztítás után, ha vissza kell állítanod a bővítmény korábbi verzióira, az minden beállításnál az alapértelmezett értékeket fogja használni.','Fluid Checkout settings cleanup' => 'A „Fluid Checkout” beállítások tisztítása','Delete leftover options' => 'A fennmaradó opciók törlése','Help us improve Fluid Checkout' => 'Segítsen nekünk a Fluid Checkout fejlesztésében!','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Ossza meg névtelen rendszerkörnyezeti jelentéseit a Fluid Checkouttal, hogy gyorsabb támogatást kapjon, és segítsen nekünk a kompatibilitás javításában és a hatások felmérésében. Az adatok nem tartalmaznak ügyfél-, felhasználói vagy érzékeny adatokat. Az „Eszközök” beállítások menüpontban bármikor kiválaszthatja, hogy milyen adatokat szeretne megosztani.','Enable site environment reports' => 'A webhelykörnyezeti jelentések engedélyezése','Review settings' => 'Beállítások áttekintése','This preview has expired. Reload the admin page to start a new preview.' => 'Ez az előnézet lejárt. Frissítse az adminisztrációs oldalt egy új előnézet elindításához.','Preview expired' => 'Az előnézet lejárt','Orders cannot be placed in the preview.' => 'Az előnézetben nem lehet megrendelést leadni.','Logging in is not available in the preview.' => 'A bejelentkezés az előnézeti verzióban nem elérhető.','Accounts cannot be created in the preview.' => 'Az előnézetben nem lehet fiókot létrehozni.','Requests to other sites are blocked in the preview.' => 'Az előnézetben a más webhelyekre irányuló lekérdezések blokkolva vannak.','Processing…' => 'Feldolgozás…','Something went wrong. Please try again.' => 'Hiba történt. Kérjük, próbálja meg újra.','Activate plugin' => 'A bővítmény aktiválása','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – A teljes pénztárcsomag','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Minden PRO funkció + minden kiegészítő, egyetlen áron. Tervezési sablonok, optimalizált kosár- és megrendelés-visszaigazoló oldalak, fiókok összehangolása és még sok más.','Optimized order pay page' => 'Optimalizált fizetési oldal','Express checkout buttons from supported payment methods' => 'A támogatott fizetési módok gyors fizetési gombjai','Delayed account creation' => 'A fiók létrehozásának késedelme','Address autocomplete with Google Maps APIs' => 'Címkiegészítés a Google Maps API-k segítségével','Multiple saved addresses with the address book' => 'Több elmentett cím a címjegyzékben','EU-VAT assistant' => 'EU-áfa-segédprogram','Hide this section' => 'E szakasz elrejtése','Learn more' => 'További információk','Get early access' => 'Korai hozzáférés','Activate add-on' => 'Kiegészítő aktiválása','Get more out of your checkout journey' => 'Hozzon ki többet a fizetési folyamatból','Test API key' => 'API-kulcs tesztelése','Guided setup' => 'Lépésről lépésre történő beállítás','Options' => 'Beállítások','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Állítsa be az elrendezést és a megjelenést a <a href="%s">fizetési lehetőségek</a> oldalon.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Engedélyezze a vendégként történő fizetést és/vagy tekintse át a <a href="%s">ügyfélfiókok beállításait</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Engedélyezze az optimalizált <a href="%1$s">kosár</a>, <a href="%2$s">köszönő</a> és <a href="%3$s">fizetési</a> oldalakat.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Engedélyezze a Google Maps <a href="%s">cím-autokomplett</a> funkcióját.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'A <a href="%s">címjegyzék</a> segítségével több címet is elmenthet.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Ellenőrizd, hogy vannak-e <a href="%s">integrációs lehetőségek</a> a témához vagy a telepített egyéb bővítményekhez.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Gyorsabb támogatást kaphat, és segíthet nekünk a kompatibilitás javításában és a hatások felmérésében. <a href="%s">Kapcsolja be a használati nyomon követést</a> az eszköz beállításaiban.','Missing settings tab.' => 'Hiányzik a „Beállítások” fül.','Getting started' => 'Első lépések','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Remek! A fizetési oldalad mostantól a Fluid Checkout rendszeren fut.</strong> Íme néhány lépés az induláshoz:','Completed' => 'Befejezve','Preview report data' => 'A jelentés adatainak előnézete','Send now' => 'Küldés most','Auto-detect' => 'Automatikus felismerés','Afrikaans' => 'afrikaans','Albanian' => 'albán','Amharic' => 'amharául','Arabic' => 'arab','Armenian' => 'örmény','Azerbaijani' => 'azeri','Basque' => 'baszk','Belarusian' => 'fehérorosz','Bengali' => 'bengáli','Bosnian' => 'bosnyák','Bulgarian' => 'bolgár','Burmese' => 'burmai','Catalan' => 'katalán','Chinese' => 'kínai','Chinese (Simplified)' => 'Kínai (egyszerűsített)','Chinese (Hong Kong)' => 'Kínai (Hongkong)','Chinese (Traditional)' => 'Kínai (hagyományos)','Croatian' => 'horvát','Czech' => 'cseh','Danish' => 'dán','Dutch' => 'holland','English' => 'angol','English (Australian)' => 'angol (ausztrál)','English (Great Britain)' => 'angol (Nagy-Britannia)','Estonian' => 'észt','Farsi' => 'perzsa','Finnish' => 'finn','Filipino' => 'filippínó','French' => 'francia','French (Canadian)' => 'francia (kanadai)','Galician' => 'galíciai','Georgian' => 'grúz','German' => 'német','Greek' => 'görög','Gujarati' => 'gudzsaráti','Hebrew' => 'héber','Hindi' => 'hindi','Hungarian' => 'magyar','Icelandic' => 'izlandi','Indonesian' => 'indonéz','Italian' => 'olasz','Japanese' => 'japán','Kannada' => 'kannada','Kazakh' => 'kazah','Khmer' => 'khmer','Korean' => 'koreai','Kyrgyz' => 'kirgiz','Lao' => 'Lao','Latvian' => 'lett','Lithuanian' => 'litván','Macedonian' => 'macedón','Malay' => 'maláj','Malayalam' => 'malajálam','Marathi' => 'maráti','Mongolian' => 'mongol','Nepali' => 'nepáli','Norwegian' => 'norvég','Polish' => 'lengyel','Portuguese' => 'portugál','Portuguese (Brazil)' => 'portugál (brazíliai)','Portuguese (Portugal)' => 'portugál (Portugália)','Punjabi' => 'pandzsábi','Romanian' => 'román','Russian' => 'orosz','Serbian' => 'szerb','Sinhalese' => 'szingaléz','Slovak' => 'szlovák','Slovenian' => 'szlovén','Spanish' => 'spanyol','Spanish (Latin America)' => 'spanyol (Latin-Amerika)','Swahili' => 'szuahéli','Swedish' => 'svéd','Tamil' => 'tamil','Telugu' => 'telugu','Thai' => 'thai','Turkish' => 'török','Ukrainian' => 'ukrán','Urdu' => 'urdú','Vietnamese' => 'vietnámi','Zulu' => 'zulu','Google address autocomplete' => 'A Google cím-autokomplett funkciója','Google Places API version' => 'A Google Places API verziója','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Válassza ki, hogy a Google Places API melyik verzióját szeretné használni. Javasoljuk, hogy a lehető leghamarabb váltson át az új Places API-ra.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Javasoljuk a „Places API (New)” használatát, mivel 2025. március 1-jétől a Google a „Places API (Legacy)” verziót „Legacy” státuszba helyezi át, ami azt jelenti, hogy új API-kulcsok esetében már nem lesz lehetőség ennek a szolgáltatásnak az engedélyezésére, és az API ezen verziója idővel teljesen elérhetetlenné válik. A már meglévő, a Legacy API-t használó fiókok továbbra is zavartalanul működhetnek.','(Recommended)' => '(Ajánlott)','Google API key' => 'Google API-kulcs','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Illessze be a Google API-kulcsát, majd a „Teszt” gomb segítségével ellenőrizze, hogy működik-e ezen a weboldalon. Győződjön meg arról, hogy a kulcs érvényes és engedélyezett a domainjéhez, ellenkező esetben a címmező blokkolódhat, ami megakadályozhatja az ügyfeleket a megrendelések véglegesítésében.','Enable Google address autocomplete' => 'A Google cím-autokomplett funkciójának engedélyezése','Enable address autocompletion using the Google Maps APIs.' => 'A Google Maps API-k segítségével engedélyezze a címek automatikus kiegészítését.','Google API language' => 'Google API nyelv','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ezt a nyelvet fogjuk használni a Google Places API címjavaslatainak megjelenítésére, és a címek automatikus kiegészítése is ezen a nyelven történik majd.','Result types' => 'Eredménytípusok','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Hagyja üresen, ha bármilyen típusú találatot elfogadni szeretne; ez általában jobb találati egyezéseket eredményez. <a href="%s" target="_blank">További részletekért lásd a dokumentációt</a>. <br>Válasszon ki legfeljebb 5 típusú címkeresési találatot, amelyek megjelenjenek a cím-autokomplett mezőkben. <br>Látogasson el a Google Maps dokumentációjába, hogy többet tudjon meg a <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">támogatott típusokról</a>.','Result types (Legacy API)' => 'Eredménytípusok (régi API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Milyen típusú címkeresési eredményeket kell visszaadni a Places API (Legacy) használata során? <br>Látogasson el a Legacy Google Places API dokumentációjába, hogy többet tudjon meg a <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">támogatott típusokról</a>.','Company fields' => 'Vállalati mezők','Enable autocomplete for the company name if available' => 'Ha lehetséges, engedélyezze a cégnév automatikus kiegészítését','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Engedélyezze a „cég” mező automatikus kiegészítését a Google Maps API-kból kapott cégnév-adatokkal.','Business search' => 'Cégkeresés','Enable search for businesses in the company field' => 'A „cég” mezőben a vállalkozásokra vonatkozó keresés engedélyezése','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'A „Cég” mezőbe történő beíráskor engedélyezze a vállalkozáshoz tartozó címek javaslatainak megjelenítését, majd a javaslatok közül egy vállalkozás kiválasztásakor töltse ki automatikusan az összes címmezőt.','Company result types' => 'A vállalat eredménytípusai','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Válasszon ki legfeljebb 5 típusú címkeresési eredményt, amelyek megjelenjenek a vállalati mezők automatikus kiegészítésénél. <br>Az ajánlott érték a <code>létesítmény</code>, amely magában foglalja a vállalkozások legtöbb típusát. <br>Ha üresen hagyja, akkor bármilyen típusú eredményt elfogad, beleértve azokat is, amelyek nem kapcsolódnak vállalkozásokhoz. <br>Látogasson el a Google Maps dokumentációjába, hogy többet tudjon meg a <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">támogatott típusokról</a>.','Google logo' => 'A Google logója','Show text and logo "Powered by Google"' => 'A „Powered by Google” szöveg és logó megjelenítése','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Ha bejelölöd, a „Powered by Google” szöveg és logó megjelenik a cím-autokomplett javaslatok mezőjének alján.','Brasil API address autocomplete' => 'Brazíliai API-cím-autokomplett','Brasil API' => 'Brazília API','Enable Brasil API address autocomplete for CEP fields' => 'A CEP-mezők esetében engedélyezze a Brasil API cím-autokomplett funkcióját','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'A Brasil API segítségével a CEP/irányítószám mező alapján lekérdezheti és automatikusan kitöltheti a címeket. Ez kizárólag brazil címekre vonatkozik.','API version' => 'API-verzió','Choose which version of the Brasil API CEP method to use.' => 'Válassza ki, hogy a Brasil API CEP-módszer melyik változatát kívánja használni.','Address book migration' => 'Címjegyzék-átvitel','WooCommerce addresses' => 'WooCommerce-címek','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'A WooCommerce-ből másolja át a meglévő szállítási és számlázási címeket az ügyfelek címjegyzékébe.','Enable the address book feature' => 'A címjegyzék funkció engedélyezése','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Lehetővé teszi az ügyfelek számára, hogy több címet is elmenthessenek, és megadják a szállításhoz és a számlázáshoz használandó alapértelmezett címet.','Address labels' => 'Címcímkék','Allow customers to add a custom label for each address' => 'Lehetővé kell tenni az ügyfelek számára, hogy minden címhez egyedi címkét adjanak hozzá','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'A címcímkék megkönnyítik az ügyfelek számára a mentett címek (pl.: „Anyu háza”) megkülönböztetését. A címcímkék az ügyfelek számára személyesek, és nem jelennek meg, illetve nem kerülnek kinyomtatásra sem a megrendelés részletei oldalon, sem a számlákon.','Display layout' => 'Kijelző elrendezése','Choose how saved addresses are displayed at checkout and on the cart.' => 'Válassza ki, hogy a mentett címek hogyan jelenjenek meg a fizetés során és a kosárban.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'A kedvezmény a fizetéskor és a kosárban érvényes. A fiókoldalon elmentett címeknél mindig a kártyás elrendezés jelenik meg.','Address cards' => 'Címkártyák','Address list' => 'Címlista','Dropdown field' => 'Legördülő menü','Address search' => 'Címkeresés','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'A címkeresési szűrőt akkor jelenítse meg a felhasználói felületen, ha az ügyfélnek legalább ennyi mentett címe van.','Not used when display layout is set to dropdown field.' => 'Nem kerül felhasználásra, ha a megjelenítési elrendezés legördülő menüre van beállítva.','Addresses' => 'Címek','Enable cart page optimizations to see more options' => 'Kapcsolja be a kosár oldalának optimalizálását, hogy további lehetőségeket láthasson','Sticky order summary' => 'Rögzített megrendelés-összefoglaló','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Válassza ki, hogy a kosár oldalon hol jelenjen meg a kuponkódok szakasz. Ez csak akkor érvényes, ha az AJAX-kosár engedélyezve van, és ha a WooCommerce beállításaiban engedélyezve van a kuponkódok használata.','Layout of cross-sell' => 'A keresztértékesítés felépítése','Cross-sells displayed' => 'Megjelenített kiegészítő termékek','Items' => 'Tételek','Cart page optimization' => 'Kosár oldal optimalizálása','Give your cart the same clear, conversion-focused layout as your checkout.' => 'A kosárnak is ugyanolyan áttekinthető, konverzióra irányuló elrendezést adjon, mint a fizetési oldalnak.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'A koherens vásárlási élmény érdekében igazítsa a kosár elrendezését a fizetési oldalhoz.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'A kosár tartalmát mindig frissítsd a háttérben; a mennyiségek változásakor ne töltődjön be újra az egész oldal.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Helyezze el a kuponkódokat, a szállítási információkat és a kiegészítő termékeket pontosan oda, ahol a leghatékonyabban eredményeznek konverziót.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Görgetés közben is láthatóvá tegye a rendelés összefoglalóját, és helyezzen el bizalomkeltő szimbólumokat ott, ahol a vásárlóknak megnyugtatásra van szükségük.','Columns' => 'Oszlopok','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'A fizetési lépések, a megrendelés összefoglalása és egyéb szakaszok általános stílusai. Alkalmazható a többi fizetési, kosár, köszönő (megrendelés beérkezett) és megrendelés-megtekintő oldalra is.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Ha a <em>„1 oszlop”</em> elrendezést a <em>„Split”</em> tervezési sablonnal együtt használja, a jobb oldali oszlop csak akkor jelenik meg, ha az oldal oldalsáv-widgetterülete aktív (Pénztár oldalsáv, Kosár oldalsáv vagy Megrendelés beérkezett oldalsáv). Ellenkező esetben az oldal egyoszlopos marad, a „Split” stílusokkal.','Split column background' => 'Oszlopok háttérének felosztása','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Válasszon háttérszínt a „Split” elrendezés másodlagos oszlopához. Ha üresen hagyja, akkor a rendelésösszefoglaló háttérszíne kerül alkalmazásra.','Page templates' => 'Oldalsablonok','Checkout template' => 'Pénztár-sablon','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Ajánlott, ha szeretné csökkenteni a fizetés során felmerülő zavaró tényezőket. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Olvassa el a kosárelhagyással kapcsolatos kutatást</a>.','Sticky progress bar' => 'Rögzített haladási sáv','Progress bar style' => 'A haladási sáv stílusa','Order totals' => 'Rendelési összegek','Background color' => 'Háttérszín','Action link' => 'Cselekvési link','Mobile order summary' => 'Mobil megrendelések összefoglalása','Mobile initial state' => 'A mobil eszköz kezdeti állapota','Enable editing cart items at checkout' => 'A kosárban lévő termékek szerkesztésének engedélyezése a fizetés során','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Lehetővé kell tenni az ügyfelek számára, hogy közvetlenül a fizetési oldalon módosítsák a termékek mennyiségét, illetve eltávolítsák az árucikkeket.','Cart item errors' => 'Kosárban lévő termékekkel kapcsolatos hibák','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Ez csak akkor érvényes, ha a kuponkód külön szakaszban jelenik meg a fizetési vagy a kosár oldalon, és ha a WooCommerce beállításaiban engedélyezve van a kuponkódok használata.','Coupon codes position' => 'Kuponkódok helye','Apply coupon button' => '„Kupon alkalmazása” gomb','Select style of the "apply coupon" button.' => 'Válassza ki a „kupon alkalmazása” gomb stílusát.','Address line 2' => '2. cím sor','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ez a beállítás a „Pénztár” és a „Helyi átvétel” szakaszokban egyaránt érvényes. A „Helyi átvétel” szakaszban ez határozza meg azt is, hogy a „Szállítás/Átvétel” választómező a szállítási módok szakaszán belül (a cím előtt) vagy külön szakaszban (utána) jelenjen-e meg.','Customer accounts' => 'Ügyfélfiókok','Guest checkout' => 'Vendégként történő fizetés','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'A WooCommerce „Fiókok” beállítási oldalán található vendégként történő fizetés, bejelentkezés és fiók létrehozás opciói. Ezeket az Ön kényelme érdekében itt kezeljük, így beállítási profilonként különböző értékeket állíthat be.','Allow customers to checkout without an account' => 'Lehetővé kell tenni az ügyfelek számára, hogy fiók nélkül is fizessenek','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Ajánlott</strong>, így a vásárlóknak nem kell fiókot létrehozniuk vagy bejelentkezniük a fizetés során, ami csökkentheti a konverziós arányt.','When disabled, customers must log in or create an account to complete the purchase.' => 'Ha ez a funkció ki van kapcsolva, az ügyfeleknek be kell jelentkezniük vagy fiókot kell létrehozniuk a vásárlás befejezéséhez.','Login at checkout' => 'Bejelentkezés a fizetéskor','Enable log-in during checkout' => 'A bejelentkezés engedélyezése a fizetési folyamat során','Show a link for returning customers to log in from the checkout page.' => 'A pénztár oldalon jelenítsen meg egy linket, amelyen keresztül a visszatérő ügyfelek bejelentkezhetnek.','Account creation' => 'Fiók létrehozása','Allow customers to create an account during checkout' => 'Lehetővé kell tenni az ügyfelek számára, hogy a fizetési folyamat során fiókot hozzanak létre','Customers can create an account before placing their order.' => 'Az ügyfelek a megrendelés leadása előtt fiókot hozhatnak létre.','Allow customers to create an account from the My account page' => 'Lehetővé kell tenni az ügyfelek számára, hogy a „Saját fiók” oldalon fiókot hozzanak létre','Customers can register a new account from the My account page.' => 'Az ügyfelek a „Saját fiók” oldalon regisztrálhatnak új fiókot.','Username' => 'Felhasználónév','Generate from customer\'s name' => 'Az ügyfél neve alapján generálás','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Ajánlott</strong>, így a vásárlóknak a fizetés során nem kell felhasználónevet választaniuk, ami csökkentheti a konverziós arányt.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'A felhasználónév az ügyfél nevéből, illetve – amennyiben a név nem használható – az e-mail-címből kerül generálásra.','Password' => 'Jelszó','Send password setup link' => 'Jelszóbeállítási link elküldése','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Ajánlott</strong>, így a vásárlóknak nem kell jelszót megadniuk a fizetés során, ami csökkentheti a konverziós arányt.','Customers receive an email to create their password securely.' => 'Az ügyfelek e-mailt kapnak, amelyben biztonságos jelszót hozhatnak létre.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Lehetővé tesszük a regisztrált ügyfelek számára, hogy bejelentkezés nélkül is végrehajtsák a fizetést, és a megrendelést a meglévő fiókjukhoz rendeljük, amennyiben az elérhetőségi adatok egyeznek.','Existing account message' => 'Üzenet a meglévő fiókról','Let customers create an account after placing their order, from the thank you page.' => 'Lehetővé tesszük az ügyfelek számára, hogy a megrendelés leadása után, az „Köszönjük!” oldalon hozzanak létre fiókot.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'A szakaszban található beállítások akkor érhetők el, ha a vendégként történő fizetés és a fiókok összekapcsolása engedélyezve van. A késleltetett fiók létrehozás beállításához engedélyezze a fenti két funkciót is.','Enable delayed account creation' => 'A fiók létrehozásának késleltetése engedélyezése','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Engedélyezze a fiók létrehozásának késleltetését, ha mind a vendégként történő fizetés, mind a fiók-összehangolás engedélyezve van.','Section position' => 'Szekció pozíciója','Before customer details section' => 'Az ügyféladatok szakasza előtt','After customer details section' => 'Az ügyféladatok szakasza után','Account creation benefits' => 'A fiók létrehozásának előnyei','Leaving the field empty will display the default text.' => 'Ha a mezőt üresen hagyja, az alapértelmezett szöveg jelenik meg.','Inline buttons' => 'Beágyazott gombok','Required fields' => 'Kötelező mezők','Enable gift message fields at checkout' => 'Az ajándéküzenet mezők engedélyezése a fizetés során','Expanded gift message' => 'Bővített ajándéküzenet','Display gift message field always expanded' => 'Az ajándéküzenet mező mindig legyen kibontva','Gift message in order details' => 'Ajándéküzenet a megrendelés részleteiben','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Jelenleg ebben a részben nincs elérhető integráció. Az egyes bővítményekhez és témákhoz kapcsolódó beállítások csak akkor jelennek meg itt, ha az adott bővítményt vagy témát aktiválják.','Phone fields' => 'Telefonos mezők','Field visibility' => 'A mező láthatósága','Field position' => 'Pályapozíció','Phone country code & validation' => 'Országkód és érvényesítés','Country' => 'Ország','Enable country on phone fields' => 'Az „Ország a telefonon” mezők engedélyezése','Filter countries for shipping or billing' => 'Országok szűrése szállítási vagy számlázási célból','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Az egyes telefonszám-mezők országválasztóját korlátozza azokra az országokra, amelyek az Ön webáruházában szállításra vagy számlázásra engedélyezettek.','Validation' => 'Érvényesítés','Enable simple validation based on country rules' => 'Egyszerű, az országonkénti szabályokon alapuló érvényesítés engedélyezése','Checks that the phone number is valid for the selected country, including country code and length.' => 'Ellenőrzi, hogy a telefonszám érvényes-e a kiválasztott országban, beleértve az országkódot és a számhosszt is.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Szigorúbb ellenőrzés annak megállapítására, hogy a szám érvényes mobilszám, vezetékes szám vagy az adott országban elfogadott egyéb típusú szám-e. Előfordulhat, hogy egyes érvényes számokat elutasít.','Validation types' => 'Ellenőrzési típusok','Placeholders' => 'Helyőrzők','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Jelenleg nincs kezelendő licenckulcs. A licenckulcsok akkor jelennek meg itt, ha egy licencelt Fluid Checkout bővítmény vagy kiegészítő aktív.','Default delivery type' => 'Alapértelmezett szállítási mód','Choose which delivery type will be selected by default.' => 'Válassza ki, melyik szállítási mód legyen az alapértelmezett.','Shipping zone fields' => 'Szállítási zóna mezők','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Válassza ki, mely mezők jelenjenek meg a helyi átvételi szállítási zóna szűrőmezőiben. Ha üresen hagyja, az összes elérhető lehetőség megjelenik.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ezek a mezők szűrőként jelennek meg a helyi átvételi szállítási módoknál. Előfordulhat, hogy egyes mezők akkor is megjelennek a fizetési oldalon, ha itt nem választják ki őket, amennyiben a kompatibilis bővítmények működéséhez szükségesek.','Order shipping address' => 'A megrendelés szállítási címe','Order pay page optimization' => 'A fizetési oldal optimalizálása','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'A ki nem fizetett megrendeléseknek is biztosítsuk ugyanazt a világos, konverzióra fókuszáló elrendezést, mint a fizetési oldalon.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimalizálja a fizetésre váró megrendelések fizetési oldalának elrendezését.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'A következetes vásárlási élmény érdekében hangolja össze a fizetési folyamatot a pénztárral.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Helyezzen el bizalmi szimbólumokat és jelvényeket azokon a helyeken, ahol a vásárlóknak biztosítékra van szükségük a fizetés előtt.','Thank you page optimization' => 'A köszönőoldal optimalizálása','Make the thank you page and order details clearer for customers after they buy.' => 'Tegye áttekinthetőbbé az ügyfelek számára a vásárlás utáni köszönőoldalt és a rendelés részleteit.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimalizálja a köszönőoldalt és a megrendelés részleteit egy áttekinthetőbb elrendezéssel.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Jelenítsd meg a megrendelés állapotának alakulását, a műveleteket, a letöltéseket és a megjegyzéseket ott, ahol azok relevánsak.','Customize order details sections on email notifications.' => 'Az e-mailes értesítésekben található megrendelés-adatok szakaszainak testreszabása.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Helyezzen el bizalmi szimbólumokat és jelvényeket ott, ahol a vásárlóknak a vásárlás után megnyugtatásra van szükségük.','Email notifications' => 'E-mailes értesítések','Enable thank you page and order details optimizations to see more options' => 'Kapcsolja be a köszönőoldal és a rendelési adatok optimalizálását, hogy további lehetőségeket láthasson','Use wide layout on thank you page' => 'Használjon széles elrendezést a köszönőoldalon','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ezek a beállítások a köszönőoldalt, a megrendelés részleteinek megjelenítését a fiókoldalakon, valamint az e-mailes értesítéseket érintik.','Save settings' => 'Beállítások mentése','Docs' => 'Dokumentumok','Cart' => 'Kosár','Thank you' => 'Köszönöm','Address autocomplete' => 'Cím-autokomplett','Trust badges' => 'Bizalmi jelvények','You do not have permission to save these settings.' => 'Nincs jogosultsága ezeket a beállításokat elmenteni.','Invalid save request.' => 'Érvénytelen mentési kérés.','Your settings have been saved.' => 'A beállítások el lettek mentve.','Saving...' => 'Mentés...','Settings could not be saved. Please try again.' => 'A beállítások mentése nem sikerült. Kérjük, próbálja meg újra.','Dismiss notice' => 'Értesítés elutasítása','Open settings menu' => 'A beállítások menü megnyitása','Close settings menu' => 'A beállítások menü bezárása','Preview' => 'Előnézet','Expand preview' => 'Előnézet kibontása','Collapse preview' => 'Előnézet összecsukása','Show header and footer' => 'Fejléc és lábléc megjelenítése','Hide header and footer' => 'Fejléc és lábléc elrejtése','Page preview' => 'Oldalelőnézet','Preview viewport' => 'Előnézeti nézőtér','Tablet' => 'Táblagép','Desktop' => 'Asztali számítógép','Preview width' => 'Előnézeti szélesség','Decrease width' => 'Szélesség csökkentése','Preview width in pixels' => 'Előnézeti szélesség pixelben','Increase width' => 'Szélesség növelése','Preview as' => 'Előnézet formátumként','Guest' => 'Vendég','Logged in' => 'Bejelentkezett','Preview page' => 'Előnézeti oldal','Expand preview for a closer look' => 'Az előnézet kibontásával részletesebben megtekintheti a képet','Available with %s.' => 'A %s-sel kapható.','Turn them on' => 'Kapcsold be őket!','Optimizations for this page are turned off. %s to preview the page.' => 'Az oldal optimalizálása ki van kapcsolva. %s az oldal előnézetéhez.','%s preview' => '%s előnézet','Isolated session · nothing is saved' => 'Elszigetelt munkamenet · semmi sem kerül mentésre','Usage tracking' => 'Használati nyomon követés','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Kérjük, küldje el a nem bizalmas webhelykörnyezeti jelentéseket, hogy segítsen a Fluid Checkoutnak a kompatibilitás javításában. A jelentések csak akkor kerülnek elküldésre, ha az alábbi beállításokban engedélyezte ezt a funkciót.','Send usage tracking reports to Fluid Checkout' => 'Használati nyomonkövetési jelentések elküldése a Fluid Checkoutnak','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ezek a jelentések segítenek nekünk javítani a webhelyed kompatibilitását és támogatását, és ha engedélyezve vannak, hetente kerülnek elküldésre.','No customer, admin user, or any other sensitive data is included in the reports.' => 'A jelentések nem tartalmaznak sem ügyfél-, sem rendszergazdai, sem egyéb érzékeny adatokat.','Basic environment info' => 'Alapvető környezeti adatok','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, témák és bővítmények listájának adatai. A jelentéskészítés engedélyezése esetén mindig szerepelnek. Segítenek megérteni, milyen környezetben működik a webhelyed.','Plugin settings' => 'A bővítmény beállításai','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Elküldi a Fluid Checkout bővítmény beállításait, hogy megkönnyítse a támogatási kérések kezelését, és segítse nekünk megérteni, hogyan használja a bővítményeinket.','Coming soon' => 'Hamarosan elérhető','Sales metrics' => 'Értékesítési mutatók','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'A Fluid Checkout telepítését megelőző egy évtől a mai napig terjedő időszak havi megrendelésszáma és összértékesítése. Ez segít nekünk megérteni, hogy többet keres-e a bővítményeink telepítésével. Ügyfél- vagy felhasználói adatokat soha nem továbbítunk.','Utilities' => 'Közművek','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'A <code>select2</code> helyett használja a <code>TomSelect</code> legördülő menü-összetevőket','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'A TomSelect egy egyszerűbb legördülő menü-komponens, amely ugyanazt a funkcionalitást kínálja, mint a Select2, ugyanakkor kevésbé hajlamos a hibákra.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'A bővítmény által optimalizált oldalakon az űrlapmezők betűméretét 16px-re állítja be, hogy kis képernyős eszközökön az űrlapmezőkkel való interakció során ne történjen automatikus nagyítás.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'A Safari és más böngészők mobil eszközökön automatikusan nagyíthatják a szöveget, hogy az könnyebben olvasható legyen, ha a betűméret kisebb, mint 16px.','Enable script processing tracking on the browser console.' => 'Engedélyezze a szkriptfeldolgozás nyomon követését a böngésző konzolján.','Unminified assets' => 'Nem minimalizált erőforrások','Google Maps scripts' => 'Google Maps szkriptek','Do not remove duplicate Google Maps scripts' => 'Ne távolítsd el az ismétlődő Google Maps-szkripteket!','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Ha ez az opció engedélyezve van, a Google Maps-szkriptek duplikátumai NEM kerülnek eltávolításra, ami hibákat és teljesítményproblémákat okozhat. Ezt az opciót kizárólag hibaelhárítás céljából használja.','Widget areas' => 'Widget-területek','Last step on mobile' => 'Utolsó lépés mobilon','Display widgets only at last step on mobile' => 'Mobil eszközökön a widgeteket csak az utolsó lépésben jelenítsd meg','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'A fizetési folyamat megbízhatósági jelvényét tartalmazó widgeteket csak akkor jelenítsd meg, ha mobil eszközön az utolsó fizetési lépés látható','Standard' => 'Szabványos','VAT number field' => 'ÁFA-szám mező','Add a VAT number field to the billing form.' => 'Adjon hozzá egy áfa-szám mezőt a számlázási űrlaphoz.','Field label' => 'Mezőcímke','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Állítsa be az áfa-szám mező címkéjét (pl. „Áfa-szám”). Többnyelvű weboldalakon célszerűbb ezt a mezőt üresen hagyni, és az eredeti szöveget lefordítani.','VAT Number' => 'ÁFA-szám','EU-VAT' => 'EU-áfa','Enable the VAT number field to see more options' => 'Jelölje be az áfa-szám mezőt a további lehetőségek megjelenítéséhez','VAT validation' => 'ÁFA-ellenőrzés','Validate VAT number field for EU-VAT during checkout' => 'Az EU-áfa-szám mező érvényességének ellenőrzése a fizetési folyamat során','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Ellenőrzi, hogy a megadott áfa-szám érvényes-e, és szerepel-e az európai VIES-adatbázisban (ÁFA-információcsere-rendszer).','Shop VAT number' => 'A bolt áfa-száma','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Az üzlet áfa-száma, amelyet az EU-áfa-ellenőrzés igényléséhez használnak, és amelyet a számlákra is rányomtatnak. <br><strong>Nyomatékosan javasoljuk, hogy adja meg az üzlet áfa-számát</strong>, mivel ellenkező esetben a VIES-lekérdezés eredményei könyvelési szempontból érvénytelenek lehetnek. <br>Például: <code>ATU99999999</code> vagy <code>EE999999999</code>.','Reverse charge' => 'Fordított adókötelezettség','Apply reverse charge mechanism' => 'A fordított adókötelezettség-rendszer alkalmazása','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Állítsa az adókulcsot nullára, és a számlákon jelenítse meg a „Fordított adókötelezettség” feliratot, ha a vevő áfa-száma érvényes. Az üzlet országától függően eltérő „Fordított adókötelezettség” felirat használata lehet szükséges.','Same country' => 'Ugyanaz az ország','Apply reverse charge mechanism for transactions in the shop country:' => 'Alkalmazzák a fordított adókötelezettség-rendszert az üzlet székhelye szerinti országban lebonyolított ügyletekre:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Lehetővé teszi a fordított adókötelezettség-rendszer alkalmazását az üzlet székhelyével azonos országban működő vállalatok közötti tranzakciók esetében.','Reverse charge exceptions' => 'A fordított adókötelezettség alóli kivételek','Select additional countries to skip applying the reverse charge mechanism.' => 'Válasszon ki további országokat, amelyek esetében el kívánja kerülni a fordított adókötelezettség-rendszer alkalmazását.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Ezekből az országokból érkező megrendelésekre adót számítunk fel akkor is, ha érvényes áfa-számot adnak meg.','Reverse charge label on invoices' => 'A számlákon szereplő fordított adókötelezettségre vonatkozó megjelölés','Set the label of "reverse charge" on the checkout page and order details.' => 'Állítsa be a „fordított adókötelezettség” jelölést a fizetési oldalon és a megrendelés részleteiben.','Reverse charge text on invoices' => 'A számlákon szereplő fordított adókötelezettségre vonatkozó szöveg','Set the label of "reverse charge" text on invoices.' => 'Állítsa be a „fordított adókötelezettség” szöveg címkéjét a számlákon.','Tax to be paid on reverse charge basis' => 'A fizetendő adó fordított adókötelezettség alapján kerül kiszámításra','Company name' => 'Cégnév','Autocomplete company name from VAT number' => 'A cégnév automatikus kiegészítése az áfa-szám alapján','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Írja be a számlázó cég nevét az ügyfél által megadott érvényes áfa-szám alapján.','Company name editing' => 'Cégnév szerkesztése','Allow editing of auto-filled company name' => 'Lehetővé teszi az automatikusan kitöltött cégnév szerkesztését','When enabled, customers can change the company name associated with the provided VAT number.' => 'Ha ez a beállítás engedélyezve van, az ügyfelek módosíthatják a megadott áfa-számhoz tartozó cégnevet.','EU-VAT for digital goods' => 'Az EU-ban a digitális termékekre vonatkozó áfa','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015. január 1-jétől módosultak az EU digitális termékekre vonatkozó áfa-szabályai, amelyek kizárólag a B2C-tranzakciókat érintik. A digitális termékekre vonatkozó áfát a vásárló tartózkodási helye alapján kell kiszámítani, és erről bizonyítékot kell gyűjteni (IP-cím és számlázási cím).','Tax classes for digital goods' => 'A digitális termékek adóbesorolása','Select some tax classes' => 'Válasszon ki néhány adóosztályt','Location evidence' => 'Helymeghatározás','Collect customer\'s location evidence' => 'Az ügyfél tartózkodási helyére vonatkozó bizonyítékok összegyűjtése','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Elmenti az IP-címet, és összehasonlítja azt az ügyfél számlázási címével. Ha a számlázási cím és az IP-cím országai nem egyeznek, az ügyfeleknek a fizetési oldalon egy jelölőnégyzet bejelölésével kell megerősíteniük a számlázási címüket.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ezt a beállítást a Fluid Checkoutban lehet kezelni. <a href="%s">A módosítást az Ügyfélfiókok beállításaiban végezheti el</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ezt a beállítást a Fluid Checkout alkalmazásban lehet kezelni. A Fluid Checkout > Ügyfélfiókok menüpont alatt módosíthatja.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ezt a beállítást a Fluid Checkout-ban lehet kezelni. A Fluid Checkout aktiválásakor a szállítási cím mindig „Alapértelmezés szerint a vásárló szállítási címe” értékre van állítva. A vásárlók a fizetési folyamat során továbbra is megadhatnak eltérő szállítási és számlázási címet.<br><br>A <a href="%s">Fluid Checkout beállítások</a> között elérhető egy opció, amellyel az alapértelmezett számlázási címet a szállítási címmel megegyezővé lehet állítani.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ezt a beállítást a Fluid Checkout-ban lehet kezelni. A Fluid Checkout aktiválásakor a szállítási cím mindig „Alapértelmezés szerint az ügyfél szállítási címe” beállításra van állítva. A vásárlók a fizetési folyamat során továbbra is megadhatnak eltérő szállítási és számlázási címet.<br><br>A WooCommerce > Beállítások > Fluid Checkout menüpontban elérhető egy beállítás, amellyel az alapértelmezett számlázási címet a szállítási címmel megegyezővé lehet tenni.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ezeket a beállításokat áthelyeztük a WP Admin > Fluid Checkout > Beállítások menüpontba.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ez a WooCommerce „Beállítások” fül elavult, és a Fluid Checkout 6.0 verzióban eltávolításra kerül.','Go to settings page' => 'Ugrás a beállítások oldalára','Hide this tab permanently' => 'Ezt a lapot véglegesen elrejtem','Site report preview' => 'A helyszíni jelentés előnézete','This is the data that would be included in the next site environment report based on your current settings.' => 'Ezek azok az adatok, amelyek a jelenlegi beállítások alapján a következő telephelyi környezeti jelentésben szerepelnének.','Loading report preview...' => 'A jelentés előnézete betöltése...','Could not load the site report preview. Try again.' => 'Nem sikerült betölteni a webhely-jelentés előnézetét. Próbálja meg újra.','Could not send the site report. Try again.' => 'A webhelyjelentés elküldése nem sikerült. Kérjük, próbálja meg újra.','Site report sent successfully.' => 'A helyszíni jelentés sikeresen elküldve.','Enable and send now' => 'Engedélyezés és azonnali elküldés','Close' => 'Bezárás','A site report request is already in progress. Try again in a moment.' => 'A helyszíni jelentés iránti kérelem feldolgozása már folyamatban van. Kérjük, próbálja meg újra egy kicsit később.','Site environment reporting is disabled.' => 'A webhely környezeti jelentései le vannak tiltva.','No site report data is available to send.' => 'Nincs elküldhető helyszíni jelentés.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ez a webhely-domain nem tud környezeti jelentéseket küldeni (a helyi és fejlesztési domainek kivételt képeznek).','A site report was sent recently. Try again later.' => 'Nemrég elküldtünk egy helyszíni jelentést. Kérjük, próbálja meg később újra.','The site report could not be sent. Try again later.' => 'A helyszíni jelentés elküldése nem sikerült. Kérjük, próbálja meg később újra.','Site environment reporting is not available.' => 'A telephely környezeti jelentései nem állnak rendelkezésre.','No site report data is available for the selected settings.' => 'A kiválasztott beállításokhoz nem állnak rendelkezésre helyszíni jelentési adatok.','You are not allowed to manage site reports.' => 'Önnek nincs jogosultsága a webhelyjelentések kezelésére.','PRO feature' => 'PRO funkció','Other plugins' => 'Egyéb bővítmények','Get only this add-on &mdash; %s' => 'Csak ezt a kiegészítőt vásárolja meg — %s','Install add-on' => 'Kiegészítő telepítése','Upgrade to PRO &mdash; %s' => 'Frissíts PRO-ra &mdash; %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Szerezd be a %2$s</a>-t, hogy feloldd ezeket az opciókat.','Add-on' => 'Kiegészítő','View documentation' => 'Dokumentáció megtekintése','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'A lekérdezésekhez bejelentkezett WordPress-felhasználóra van szükség. A user_id paraméter kihagyásával az aktuális felhasználó adatai kerülnek felhasználásra; a user_id paraméter megadásával pedig egy másik fiókra lehet hivatkozni, amennyiben a lekérdező rendelkezik az adott felhasználó szerkesztéséhez szükséges jogosultsággal (edit_user jogosultság). A hitelesítetlen lekérdezések fc_api_forbidden hibát adnak vissza. Érvénytelen user_id esetén az fc_api_user_not_found hibaüzenet kerül visszaadásra.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200, { "data": { ... } } kóddal, amikor a kezelő adatcsomagot ad vissza.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200-as kód { "success": true } értékkel, ha nincs hasznos adat (például DELETE esetén).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'A hibák a WP_Error-ból származó WordPress REST-hiba JSON-adatokat adnak vissza (kód, üzenet, data.status). A hiba-kódok az fc_api_* előtagot használják.','Forbidden access.' => 'Belépés tilos.','Target user was not found.' => 'A célfelhasználó nem található.','This feature is not available.' => 'Ez a funkció nem érhető el.','A required address field is missing.' => 'Hiányzik egy kötelezően kitöltendő címmező.','Postcode or ZIP is invalid.' => 'Az irányítószám vagy a ZIP-kód érvénytelen.','Phone number is invalid.' => 'A telefonszám érvénytelen.','State or county is invalid.' => 'Az állam vagy a megye megadása érvénytelen.','Country is invalid or has no address fields.' => 'Az ország megadása érvénytelen, vagy nincs címmező.','The request could not be processed.' => 'A kérés feldolgozása nem sikerült.','Back to previous step' => 'Vissza az előző lépéshez','Skip to settings' => 'Ugrás a beállításokra','Start over and return to the first guided setup step' => 'Kezdje elölről, és térjen vissza az első vezérelt beállítási lépéshez','Start over' => 'Újrakezdés','Please complete all sub-steps before continuing.' => 'Kérjük, hajtsa végre az összes al-lépést, mielőtt továbbhaladna.','Expand' => 'Bontás','Collapse' => 'Összecsukás','Skip' => 'Ugrás','Mark as complete' => 'Befejezettként jelölés','Mark as incomplete' => 'Jelölje meg befejezetlenként','View full-size image: %s' => 'Kép teljes méretben: %s','Full-size setup guide image' => 'Teljes méretű telepítési útmutató kép','Close image' => 'Kép bezárása','Fluid Checkout Guided Setup' => 'Fluid Checkout vezérelt beállítás','Welcome' => 'Üdvözöljük!','Explore your checkout' => 'Fedezze fel a fizetési folyamatot','All set' => 'Minden készen áll','You do not have permission to access this page.' => 'Nincs jogosultsága az oldal eléréséhez.','Go to step %1$d: %2$s' => 'Ugrás a %1$d. lépésre: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ez az irányított beállítási útmutató segít megismerkedni a Fluid Checkout szolgáltatással. Az alábbi lépések egyelőre csak helyfoglalók.','Continue to the next step when you are ready.' => 'Ha készen áll, folytassa a következő lépéssel.','Open your store checkout to see Fluid Checkout in action.' => 'Nyissa meg az üzlet pénztárát, hogy élőben megtekintse a Fluid Checkout működését.','View checkout page' => 'A fizetési oldal megtekintése','You can return to Fluid Checkout settings to continue configuring your store.' => 'Visszatérhet a Fluid Checkout beállításaihoz, hogy folytassa az áruház konfigurálását.','Review checkout and cart settings' => 'A fizetési és kosárbeállítások áttekintése','Explore add-ons from the dashboard' => 'Fedezze fel a kiegészítőket a vezérlőpulton','Finish & go to settings' => 'Befejezés és a beállításokhoz lépés','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'A számlázási telefonszám mező láthatósági beállítását módosítsa a korábbi értékről úgy, hogy az megfeleljen a WooCommerce szabályainak.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'A szállítási telefonszám mező láthatósági beállítását módosítsd a korábbi értékről úgy, hogy az megfeleljen a WooCommerce szabályainak.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Másolja át a megrendelés-összefoglaló háttérszín-beállítását az új „Split” terv másodlagos oszlop háttérszín-beállításába.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'A „Kiterjesztett mezőválasztás” funkció a Biteship bővítmény használata esetén mindig le van tiltva.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'A „German Market” használata esetén a megbízás elhelyezésének pozíciója mindig „A megbízás összefoglalása alatt” beállításra van állítva. Ez a bővítmény megköveteli, hogy a megbízás elhelyezése gomb és a jogi jelölőnégyzetek a megbízás összefoglalása alatt jelenjenek meg.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'A „Germanized for WooCommerce” bővítmény használata esetén a megrendelés leadásának helye mindig „A megrendelés összefoglalása alatt” beállításra van állítva. Ez a bővítmény előírja, hogy a megrendelés leadására szolgáló gomb és a jogi nyilatkozatokhoz tartozó jelölőnégyzetek a megrendelés összefoglalása alatt jelenjenek meg.','Edit pickup locations' => 'A felvételi helyek szerkesztése','Use local pickup label from WooCommerce settings' => 'A WooCommerce beállításaiból válassza ki a helyi átvételi címkét','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Ha engedélyezve van, a fizetés során megjelenő „átvétel” opció felirata megegyezik a WooCommerce átvételi hely beállításaiban megadott címmel. Ha letiltva van, a felirat a Fluid Checkoutból származó, lefordítható „Helyi átvétel” szöveget használja.','Button label for applying coupon codesApply' => 'Alkalmazás','Checkout step titleContact' => 'Kapcsolat','Checkout step titleShipping' => 'Szállítás','Checkout step titleBilling' => 'Számlázás','Checkout step titlePayment' => 'Fizetés','Checkout substep change link labelChange' => 'Változás','Checkout substep save link labelSave changes' => 'Változások mentése','Substep review textNone.' => 'Nincs.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nincs kiválasztott kép.','Settings sectionCart' => 'Kosár','Settings sectionOrder pay' => 'Fizetés megrendelése','Settings sectionThank you' => 'Köszönöm.','Settings section titleIntegrations' => 'Integrációk','Settings section titleLicense keys' => 'Licenckulcsok','Captcha positionBefore place order section' => 'A megrendelés előtt szakasz','Captcha positionBefore place order button' => 'A megrendelés gomb előtt','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Zárja be a','Log in link label at checkout contact stepLog in' => 'Bejelentkezés','Log in separator label at for when guest checkout is disabledOr continue below' => 'Vagy folytassa alább','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Vagy folytassa vendégként','Clear image selection on admin pages.Remove image' => 'Kép eltávolítása','shipping packagesShipping %d' => 'Szállítás %d','shipping packagesShipping' => 'Szállítás','Used as fallback for "Proceed to next step" button labelnext step' => 'következő lépés','Substep review checkbox valueYes' => 'Igen','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'John','Dummy customer last name in the admin previewDoe' => 'Doe','Dummy customer company in the admin previewExample Company' => 'Példa cég','Dummy customer street address in the admin preview123 Main Street' => '123 Főutca','Dummy customer city in the admin previewAnytown' => 'Bármelyik város','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Kérjük, hagyja a csomagot a bejárati ajtó előtt.','Dummy product name in the admin previewBeanie' => 'Sapka','Dummy product name in the admin previewCap' => 'Sapka','Dummy product name in the admin previewT-Shirt' => 'Póló','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Megkaptuk a megrendelését, és értesítjük Önt, amint a csomagot feladjuk.','Dummy download in the admin previewUser guide' => 'Használati útmutató','Google Places API versionsPlaces API (New)' => 'Places API (Új)','Google Places API versionsPlaces API (Legacy)' => 'Places API (régi verzió)','Brasil API versionsVersion 1' => '1. verzió','Brasil API versionsVersion 2' => '2. verzió','Delayed account creation benefits placeholder text✔ Checkout faster next time
